        });
    }
});

I had an issue with YEP_SaveMenuCore which I am also using. It allowes me to reload any other save file from within the Save Scene. Adding the following code to your plugin solved the issue for me:
Code:
this.extend(Scene_File, "onLoadSuccess", function () {
        _this.debug("Loading new save...", "Force to re-load whole tileset!");
        _savedLayer = null; _flags = null; _savedLayer = null;
        _currentShaderTilemap = null; _cacheReady = false;
        _tileSprites = []; _doCulling = false;
        _this["Scene_File_onLoadSuccess"].apply(this, arguments); return;
    });

